#nullable enable
using Microsoft.AspNetCore.Mvc;using Modular.Modules.Contracts;using Modular.Modules.LicenseManagement.Application;namespace Modular.Modules.LicenseManagement.Controllers;
[Route("admin/licenses")]public sealed class LicensesController:Controller{readonly LicenseManagementService service;public LicensesController(LicenseManagementService s)=>service=s;[HttpGet("")]public IActionResult Index()=>View(service.List());[HttpGet("create")]public IActionResult Create()=>View(new LicenseInput("","","",null,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow.AddYears(1),Array.Empty<string>()));[HttpPost("create"),ValidateAntiForgeryToken]public IActionResult Create(LicenseInput x){var r=service.Register(x);return r.Succeeded?RedirectToAction(nameof(Details),new{id=r.Value!.Id}):Invalid(x,r.Errors);}[HttpGet("{id}")]public IActionResult Details(Guid id)=>service.Get(id) is{} x?View(x):NotFound();[HttpPost("{id}/activate"),ValidateAntiForgeryToken]public IActionResult Activate(Guid id,string? tenantId){var r=service.Activate(id,tenantId);if(!r.Succeeded)TempData["Error"]=string.Join(" ",r.Errors);return RedirectToAction(nameof(Details),new{id});}[HttpPost("{id}/features"),ValidateAntiForgeryToken]public IActionResult Feature(Guid id,string code,bool enabled=true){var r=service.AssignFeature(id,code,enabled);if(!r.Succeeded)TempData["Error"]=string.Join(" ",r.Errors);return RedirectToAction(nameof(Details),new{id});}IActionResult Invalid(LicenseInput x,IEnumerable<string> es){foreach(var e in es)ModelState.AddModelError("",e);return View("Create",x);}}
